def modify(model, targets):
    target_ids = {item.id() for item in targets}
    for item in targets:
        # Find instance-level pset only (not from type)
        pset_data = None
        for rel in model.by_type("IfcRelDefinesByProperties"):
            if any(o.id() in target_ids and o == item for o in rel.RelatedObjects):
                pset_candidate = rel.RelatingPropertyDefinition
                if pset_candidate.is_a("IfcPropertySet") and pset_candidate.Name == "Identity Data":
                    pset_data = pset_candidate
                    break

        if pset_data is None:
            pset_data = ifcopenshell.api.run("pset.add_pset", model, product=item, name="Identity Data")

        ifcopenshell.api.run("pset.edit_pset", model, pset=pset_data, properties={"Reference": "LR"})

